import pprint

class DottedPrettyPrinter(pprint.PrettyPrinter):

    def format(self, object, context, maxlevels, level):
        if isinstance(object, str):
            if ' ' in object:
                return (repr(object), 1, 0)
            else:
                return (object, 0, 0)
        else:
            return pprint.PrettyPrinter.format(self, object, context, maxlevels, level)

def _t():

    class _SelfNS:
        pass
    self = _SelfNS()
    self.a = list(range(100))
    self.b = list(range(200))
    self.a[-12] = self.b
    o = {'names with spaces': 'should be presented using repr()', 'others.should.not.be': 'like.this'}
    exp = "{'names with spaces': 'should be presented using repr()',\n others.should.not.be: like.this}"
    dotted_printer = DottedPrettyPrinter()
    assert dotted_printer.pformat(o) == exp, ('assertEqual', dotted_printer.pformat(o), exp)
    o1 = ['with space']
    exp1 = "['with space']"
    assert dotted_printer.pformat(o1) == exp1, ('assertEqual', dotted_printer.pformat(o1), exp1)
    o2 = ['without.space']
    exp2 = '[without.space]'
    assert dotted_printer.pformat(o2) == exp2, ('assertEqual', dotted_printer.pformat(o2), exp2)
