import pprint

class Unorderable:

    def __repr__(self):
        return str(id(self))

class Orderable:

    def __init__(self, hash):
        self._hash = hash

    def __lt__(self, other):
        return False

    def __gt__(self, other):
        return self != other

    def __le__(self, other):
        return self == other

    def __ge__(self, other):
        return True

    def __eq__(self, other):
        return self is other

    def __ne__(self, other):
        return self is not other

    def __hash__(self):
        return self._hash

def _t():

    class _SelfNS:
        pass
    self = _SelfNS()
    self.a = list(range(100))
    self.b = list(range(200))
    self.a[-12] = self.b
    a = Unorderable()
    b = Orderable(hash(a))
    assert a < b, ('assertLess', a, b)
    assert str(type(b)) < str(type(a)), ('assertLess', str(type(b)), str(type(a)))
    assert sorted([b, a]) == [a, b], ('assertEqual', sorted([b, a]), [a, b])
    assert sorted([a, b]) == [a, b], ('assertEqual', sorted([a, b]), [a, b])
    assert pprint.pformat(set([b, a]), width=1) == '{%r,\n %r}' % (a, b), ('assertEqual', pprint.pformat(set([b, a]), width=1), '{%r,\n %r}' % (a, b))
